"""Readable notebook cells for mitigation and its order-sensitivity analysis."""
from __future__ import annotations


def order_plot_wording(family, *, outcome_window):
    """Keep the mean baseline predictor distinct from the outcome time window."""
    if outcome_window not in {"mean_1_30", "iteration_30"}:
        raise ValueError("Order associations use either mean_1_30 or iteration_30 outcomes")
    computational = str(family).startswith("Computational")
    family_name = "computational models" if computational else "LLM models"
    predictor = "Item-choice probability TVD" if computational else "Replica agreement minus shuffled agreement"
    definition = ("TVD between saved item-choice probabilities aligned by item identity" if computational else
                  "replica agreement minus shuffled agreement, calculated on the common canonical/replica/shuffled valid-click subset")
    time = "mean over iterations 1–30" if outcome_window == "mean_1_30" else "iteration-30"
    title_time = "Mean" if outcome_window == "mean_1_30" else "Iteration-30"
    outcome = ("the mean over iterations 1–30 of paired control-minus-post-processing Head-click share differences"
               if outcome_window == "mean_1_30" else
               "the control-minus-post-processing Head-click share difference at iteration 30")
    return {"title": f"{title_time} total post-processing reduction versus order sensitivity: {family_name}",
            "x_label": f"{predictor} (control mean, iterations 1–30)",
            "y_label": f"Total Head-click share reduction (pp; {time})",
            "caption": f"Each point is one response-model configuration within a seed. The predictor is {definition}, "
                       f"averaged over the unmitigated control iterations 1–30. The outcome is {outcome}, in percentage points. "
                       "This is the total reduction, combining the immediate-reranking and feedback/state components reported separately in RQ IV. "
                       "Positive outcomes indicate a reduction in head-click share under post-processing. "
                       "Both runs use the same model, feedback stage, population, and seed; predictor families are not pooled."}


